input.command:
swift -e '
import Foundation
import PDFKit
import AppKit

let pdfPath = "/Users/stark/Desktop/张馨妍-名字由来/张馨妍-名字由来.pdf"
let outDir = "/Users/stark/Desktop/张馨妍-名字由来/preview"
try? FileManager.default.createDirectory(atPath: outDir, withIntermediateDirectories: true)
guard let doc = PDFDocument(url: URL(fileURLWithPath: pdfPath)) else { fputs("open fail\n", stderr); exit(1) }
print("pages \(doc.pageCount)")
for i in 0..<doc.pageCount {
    guard let page = doc.page(at: i) else { continue }
    let img = page.thumbnail(of: CGSize(width: 1240, height: 1754), for: .mediaBox)
    guard let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff),
          let data = rep.representation(using: .png, properties: [:]) else { continue }
    let out = "\(outDir)/page-\(String(format: "%02d", i+1)).png"
    try data.write(to: URL(fileURLWithPath: out))
    print("wrote \(out)")
}
'
